"use client";

import * as React from "react";
import { CheckCircle2, Loader2, Play, Send, TriangleAlert } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { cn } from "@/lib/utils";

export type AdapterStatus = "idle" | "submitting" | "success" | "error";

export type PowerAppsSubmitResult = {
  id: string;
  message: string;
};

export type PowerAppsAdapter = {
  name: string;
  submit: (values: Record<string, string>) => Promise<PowerAppsSubmitResult>;
};

export type PowerAppsVisualProps = {
  adapter?: PowerAppsAdapter;
  /** Enables the explicit local mock used by the documentation gallery. */
  mock?: boolean;
  value?: Record<string, string>;
  defaultValue?: Record<string, string>;
  onValueChange?: (values: Record<string, string>) => void;
  onSubmitted?: (result: PowerAppsSubmitResult) => void;
  className?: string;
};

export type PowerAutomateRunResult = {
  runId: string;
  status: "queued" | "succeeded";
  message: string;
};

export type PowerAutomateAdapter = {
  name: string;
  trigger: (flowId: string, payload: Record<string, string>) => Promise<PowerAutomateRunResult>;
};

export type PowerAutomateVisualProps = {
  flowId: string;
  adapter?: PowerAutomateAdapter;
  /** Enables the explicit local mock used by the documentation gallery. */
  mock?: boolean;
  defaultPayload?: Record<string, string>;
  onRunComplete?: (result: PowerAutomateRunResult) => void;
  className?: string;
};

function MockBadge() {
  return (
    <span className="rounded-full border border-border bg-muted px-2 py-1 text-[11px] font-semibold text-muted-foreground">
      Mock adapter
    </span>
  );
}

function AdapterMissing({ product }: { product: string }) {
  return (
    <div className="rounded-lg border border-dashed border-[var(--chart-warning)]/50 bg-[var(--chart-warning)]/5 p-4" role="status">
      <div className="flex items-center gap-2 font-semibold"><TriangleAlert className="h-4 w-4" />Adapter required</div>
      <p className="mt-1 text-sm text-muted-foreground">
        Supply an authorized {product} adapter. No provider SDK, credentials, iframe, or remote action is bundled.
      </p>
    </div>
  );
}

const mockPowerAppsAdapter: PowerAppsAdapter = {
  name: "Local write-back mock",
  async submit(values) {
    return {
      id: `mock-${Object.keys(values).sort().join("-") || "submission"}`,
      message: "Mock write-back accepted locally. No external application was contacted.",
    };
  },
};

const mockPowerAutomateAdapter: PowerAutomateAdapter = {
  name: "Local flow mock",
  async trigger(flowId, payload) {
    return {
      runId: `mock-${flowId}-${Object.keys(payload).length}`,
      status: "succeeded",
      message: "Mock flow completed locally. No external automation was triggered.",
    };
  },
};

export function PowerAppsVisual({
  adapter,
  mock = false,
  value,
  defaultValue = { project: "North expansion", owner: "Alex", forecast: "125000" },
  onValueChange,
  onSubmitted,
  className,
}: PowerAppsVisualProps) {
  const activeAdapter = adapter ?? (mock ? mockPowerAppsAdapter : undefined);
  const [internalValue, setInternalValue] = React.useState(defaultValue);
  const [status, setStatus] = React.useState<AdapterStatus>("idle");
  const [message, setMessage] = React.useState("");
  const current = value ?? internalValue;
  const update = (key: string, nextValue: string) => {
    const next = { ...current, [key]: nextValue };
    if (value === undefined) setInternalValue(next);
    onValueChange?.(next);
    setStatus("idle");
    setMessage("");
  };
  const submit = async (event: React.FormEvent) => {
    event.preventDefault();
    if (!activeAdapter) return;
    setStatus("submitting");
    try {
      const result = await activeAdapter.submit(current);
      setStatus("success");
      setMessage(result.message);
      onSubmitted?.(result);
    } catch (reason) {
      setStatus("error");
      setMessage(reason instanceof Error ? reason.message : String(reason));
    }
  };

  return (
    <div className={cn("space-y-3 rounded-xl border border-border bg-card p-4", className)}>
      <div className="flex flex-wrap items-center justify-between gap-2">
        <div>
          <div className="font-semibold">Application write-back adapter</div>
          <div className="text-xs text-muted-foreground">Independent integration surface; not affiliated with Microsoft Power Apps.</div>
        </div>
        {mock ? <MockBadge /> : null}
      </div>
      {!activeAdapter ? <AdapterMissing product="Power Apps" /> : (
        <form className="grid gap-3 sm:grid-cols-2" onSubmit={submit}>
          {Object.entries(current).map(([key, fieldValue]) => (
            <label key={key} className="space-y-1 text-xs font-medium capitalize">
              {key}
              <Input value={fieldValue} onChange={(event) => update(key, event.target.value)} disabled={status === "submitting"} />
            </label>
          ))}
          <div className="flex items-center gap-3 sm:col-span-2">
            <Button type="submit" size="sm" disabled={status === "submitting"}>
              {status === "submitting" ? <Loader2 className="h-4 w-4 animate-spin" /> : <Send className="h-4 w-4" />}
              Submit write-back
            </Button>
            <span className="text-xs text-muted-foreground">{activeAdapter.name}</span>
          </div>
        </form>
      )}
      {message ? (
        <div className={cn("flex items-start gap-2 rounded-lg p-3 text-sm", status === "error" ? "bg-[var(--chart-negative)]/8" : "bg-[var(--chart-positive)]/8")} role={status === "error" ? "alert" : "status"}>
          {status === "error" ? <TriangleAlert className="mt-0.5 h-4 w-4" /> : <CheckCircle2 className="mt-0.5 h-4 w-4" />}
          {message}
        </div>
      ) : null}
    </div>
  );
}

export function PowerAutomateVisual({
  flowId,
  adapter,
  mock = false,
  defaultPayload = { report: "Operations", period: "Q3" },
  onRunComplete,
  className,
}: PowerAutomateVisualProps) {
  const activeAdapter = adapter ?? (mock ? mockPowerAutomateAdapter : undefined);
  const [status, setStatus] = React.useState<AdapterStatus>("idle");
  const [result, setResult] = React.useState<PowerAutomateRunResult | null>(null);
  const run = async () => {
    if (!activeAdapter || !flowId.trim()) return;
    setStatus("submitting");
    setResult(null);
    try {
      const next = await activeAdapter.trigger(flowId, defaultPayload);
      setResult(next);
      setStatus("success");
      onRunComplete?.(next);
    } catch (reason) {
      setStatus("error");
      setResult({ runId: "", status: "queued", message: reason instanceof Error ? reason.message : String(reason) });
    }
  };

  return (
    <div className={cn("space-y-4 rounded-xl border border-border bg-card p-4", className)}>
      <div className="flex flex-wrap items-start justify-between gap-2">
        <div>
          <div className="font-semibold">Automation trigger adapter</div>
          <div className="text-xs text-muted-foreground">Independent integration surface; not affiliated with Microsoft Power Automate.</div>
        </div>
        {mock ? <MockBadge /> : null}
      </div>
      {!activeAdapter ? <AdapterMissing product="Power Automate" /> : (
        <div className="flex flex-wrap items-center gap-3">
          <Button type="button" size="sm" onClick={run} disabled={status === "submitting" || !flowId.trim()}>
            {status === "submitting" ? <Loader2 className="h-4 w-4 animate-spin" /> : <Play className="h-4 w-4" />}
            Trigger {flowId}
          </Button>
          <span className="text-xs text-muted-foreground">{activeAdapter.name}</span>
        </div>
      )}
      {result ? (
        <div className="rounded-lg bg-muted/60 p-3 text-sm" role={status === "error" ? "alert" : "status"}>
          <div className="font-medium">{result.message}</div>
          {result.runId ? <div className="mt-1 font-mono text-xs text-muted-foreground">Run {result.runId}</div> : null}
        </div>
      ) : null}
    </div>
  );
}
